const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Kendeord</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Det tyske kendeord passer ikke altid med ordets køn på dansk. Derfor er det bedst at lære navneord sammen med kendeordet.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Eksempler på kendeord</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — bord</div>\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">das Mädchen — pige</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Ofte DER</h4>\n    <p class=\"artikuli-explain\">DER bruges ofte om personer af hankøn, dage, måneder, årstider og nogle ord med bestemte endelser.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → ofte DER, for eksempel: der Computer, der Lehrer <span class=\"artikuli-note\">men ikke altid</span></div>\n      <div class=\"kurss-example\">-ling → ofte DER, for eksempel: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → ofte DER, for eksempel: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">personer af hankøn → der Mann, der Vater</div>\n      <div class=\"kurss-example\">erhverv → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">bilmærker → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dage → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">måneder → der August, der Dezember</div>\n      <div class=\"kurss-example\">årstider → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mand</div>\n      <div class=\"kurss-example\">der Vater — far</div>\n      <div class=\"kurss-example\">der Montag — mandag</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — sommer</div>\n      <div class=\"kurss-example\">der Lehrer — lærer</div>\n      <div class=\"kurss-example\">der Computer — computer</div>\n      <div class=\"kurss-example\">der Schmetterling — sommerfugl</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Ofte DIE</h4>\n    <p class=\"artikuli-explain\">DIE bruges ofte om personer af hunkøn, flertal og ord med endelserne -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">personer af hunkøn → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motorcykelmærker → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">flertal → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">flertal næsten altid → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kvinde</div>\n      <div class=\"kurss-example\">die Mutter — mor</div>\n      <div class=\"kurss-example\">die Wohnung — lejlighed</div>\n      <div class=\"kurss-example\">die Rechnung — regning</div>\n      <div class=\"kurss-example\">die Freiheit — frihed</div>\n      <div class=\"kurss-example\">die Möglichkeit — mulighed</div>\n      <div class=\"kurss-example\">die Mannschaft — hold</div>\n      <div class=\"kurss-example\">die Nation — nation</div>\n      <div class=\"kurss-example\">die Universität — universitet</div>\n      <div class=\"kurss-example\">die Polizei — politi</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Ofte DAS</h4>\n    <p class=\"artikuli-explain\">DAS bruges ofte om diminutiver med -chen / -lein, mange ord med -ment / -um og udsagnsord brugt som navneord.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metaller → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">grundstoffer → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hoteller → das Hotel</div>\n      <div class=\"kurss-example\">farver som navneord → das Rot, das Blau</div>\n      <div class=\"kurss-example\">udsagnsord som navneord → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">udsagnsord som navneord → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — barn</div>\n      <div class=\"kurss-example\">das Mädchen — pige</div>\n      <div class=\"kurss-example\">das Häuschen — lille hus</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centrum</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — spisning / mad</div>\n      <div class=\"kurss-example\">das Lernen — læring</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Vigtige undtagelser / skal læres med kendeord</h4>\n    <p class=\"artikuli-explain\">For nogle ord kan man ikke sikkert afgøre kendeordet ud fra endelsen eller ordets køn på dansk. Dem er det bedst at lære sammen med kendeordet.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — måne</div>\n      <div class=\"kurss-example\">das Mädchen — pige</div>\n      <div class=\"kurss-example\">das Auto — bil</div>\n      <div class=\"kurss-example\">der Käse — ost</div>\n      <div class=\"kurss-example\">die Gabel — gaffel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Endelser og ordgrupper hjælper med at gætte kendeordet, men de er ikke en 100% sikker regel. Hvis du er i tvivl, så lær ordet sammen med kendeordet.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Stedord</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ og Dativ — stedordenes former.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — hvem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — jeg</div><div class=\"kurss-example\">du — du</div><div class=\"kurss-example\">er — han</div><div class=\"kurss-example\">sie — hun</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">wir — vi</div><div class=\"kurss-example\">ihr — I</div><div class=\"kurss-example\">sie — de</div><div class=\"kurss-example\">Sie — De (høfligt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — hvem/hvad?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mig</div><div class=\"kurss-example\">dich — dig</div><div class=\"kurss-example\">ihn — ham (hank.)</div><div class=\"kurss-example\">sie — hende (hunk.)</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">uns — os</div><div class=\"kurss-example\">euch — jer</div><div class=\"kurss-example\">sie — dem</div><div class=\"kurss-example\">Sie — Dem (høfligt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — til hvem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (til) mig</div><div class=\"kurss-example\">dir — (til) dig</div><div class=\"kurss-example\">ihm — (til) ham / det</div><div class=\"kurss-example\">ihr — (til) hende</div><div class=\"kurss-example\">uns — (til) os</div><div class=\"kurss-example\">euch — (til) jer</div><div class=\"kurss-example\">ihnen — (til) dem</div><div class=\"kurss-example\">Ihnen — (til) Dem (høfligt)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hvordan vælger man formen?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — grundled (hvem gør noget?)</li><li><span class=\"case-red\">Akkusativ</span> — genstandsled (hvem/hvad?)</li><li><span class=\"case-green\">Dativ</span> — hensynsled (til hvem?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Eksempler</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Jeg ser dig.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Jeg ser ham.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Vi kan godt lide jer.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Jeg hjælper dig.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Jeg giver ham en bog.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vi takker jer.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ er altid sætningens grundled, mens Akkusativ og Dativ er objekter. Se på udsagnsordet, og spørg: <span class=\"case-red\">hvem/hvad?</span> eller <span class=\"case-green\">til hvem?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vokaler — lange og korte</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>På tysk kan vokaler være lange eller korte. Det påvirker, hvordan ordet udtales.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lang vokal</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — varm</div><div class=\"kurss-example\">gut (gūt) — god</div><div class=\"kurss-example\">Tat (tāt) — gerning / handling</div><div class=\"kurss-example\">Flur (flūr) — gang / entré</div><div class=\"kurss-example\">Weg (vēk) — vej</div><div class=\"kurss-example\">Hut (hūt) — hat</div><div class=\"kurss-example\">Hof (hōf) — gård</div><div class=\"kurss-example\">Schlaf (sjlāf) — søvn</div></div>\n              <p class=\"artikuli-explain\">Hvis der kommer én konsonant efter vokalen, udtales vokalen ofte lang.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kort vokal</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — svamp</div><div class=\"kurss-example\">Wort (vort) — ord</div><div class=\"kurss-example\">Mund (munt) — mund</div><div class=\"kurss-example\">bald (balt) — snart</div><div class=\"kurss-example\">scharf (sjarf) — skarp</div><div class=\"kurss-example\">Feld (felt) — mark</div><div class=\"kurss-example\">voll (fol) — fuld</div></div>\n              <p class=\"artikuli-explain\">Hvis der kommer to eller flere konsonanter efter vokalen, udtales vokalen ofte kort.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endelserne en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">tragen (trāgen) — bære</div><div class=\"kurss-example\">Garten (garten) — have</div><div class=\"kurss-example\">Vogel (fōgel) — fugl</div><div class=\"kurss-example\">Segel (zēgel) — sejl</div><div class=\"kurss-example\">Braten (brāten) — steg</div><div class=\"kurss-example\">Bogen (bōgen) — bue</div><div class=\"kurss-example\">Spiegel (sjpīgel) — spejl</div><div class=\"kurss-example\">Finger (finger) — finger</div><div class=\"kurss-example\">Halter (halter) — holder</div><div class=\"kurss-example\">Arbeiter (arbajter) — arbejder</div><div class=\"kurss-example\">Häuser (hojzer) — huse</div><div class=\"kurss-example\">wieder (vīder) — igen</div><div class=\"kurss-example\">breiter (brajter) — bredere</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Bogstavet h som længdetegn</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rāmen) — ramme</div><div class=\"kurss-example\">Ohr (ōr) — øre</div><div class=\"kurss-example\">Kohle (kōle) — kul</div><div class=\"kurss-example\">Zahl (tsāl) — tal</div><div class=\"kurss-example\">ihn (īn) — ham</div><div class=\"kurss-example\">ihm (īm) — (til) ham</div><div class=\"kurss-example\">Huhn (hūn) — høne</div><div class=\"kurss-example\">nahm (nām) — tog</div><div class=\"kurss-example\">nehmen (nēmen) — tage</div><div class=\"kurss-example\">Schuh (sjū) — sko</div></div>\n              <p class=\"artikuli-explain\">I nogle ord forlænger h den foregående vokal. I sådanne tilfælde udtales h normalt ikke.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Endelser på e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lampe</div><div class=\"kurss-example\">Hase (hāze) — hare</div><div class=\"kurss-example\">Knabe (knābe) — dreng</div><div class=\"kurss-example\">Rabe (rābe) — ravn</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Langt i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dī) — den bestemte artikel »die«</div><div class=\"kurss-example\">diese (dīze) — denne / disse</div><div class=\"kurss-example\">wieder (vīder) — igen</div><div class=\"kurss-example\">Fliege (flīge) — flue</div><div class=\"kurss-example\">Ziege (tsīge) — ged</div><div class=\"kurss-example\">Stiel (sjtīl) — stilk / skaft</div><div class=\"kurss-example\">Dieb (dīp) — tyv</div><div class=\"kurss-example\">hier (hīr) — her</div></div>\n              <p class=\"artikuli-explain\">Langt i skrives på tysk ofte som ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dobbeltvokaler</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zāl) — sal</div><div class=\"kurss-example\">Saat (zāt) — sæd / såning</div><div class=\"kurss-example\">Staat (sjtāt) — stat</div><div class=\"kurss-example\">Beere (bēre) — bær</div><div class=\"kurss-example\">See (zē) — sø / hav</div><div class=\"kurss-example\">Beet (bēt) — bed</div><div class=\"kurss-example\">Boot (bōt) — båd</div><div class=\"kurss-example\">Moor (mōr) — mose</div><div class=\"kurss-example\">Moos (mōs) — mos</div></div>\n              <p class=\"artikuli-explain\">Dobbeltvokaler udtales normalt lange.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — væg</div><div class=\"kurss-example\">Wände (vænde) — vægge</div><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">Väter (fēter) — fædre</div><div class=\"kurss-example\">Schrank (sjrank) — skab</div><div class=\"kurss-example\">Schränke (sjrænke) — skabe</div><div class=\"kurss-example\">Bank (bank) — bænk / bank</div><div class=\"kurss-example\">Bänke (bænke) — bænke</div><div class=\"kurss-example\">Tal (tāl) — dal</div><div class=\"kurss-example\">Täler (tēler) — dale</div></div>\n              <p class=\"artikuli-explain\">ä er omlyden af a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rōze) — rose</div><div class=\"kurss-example\">Röschen (rø̄s-chen) — lille rose</div><div class=\"kurss-example\">Ofen (ōfen) — ovn</div><div class=\"kurss-example\">Öfen (ø̄fen) — ovne</div><div class=\"kurss-example\">Rock (rok) — nederdel</div><div class=\"kurss-example\">Röcke (røke) — nederdele</div></div>\n              <p class=\"artikuli-explain\">ö er omlyden af o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurts) — kort</div><div class=\"kurss-example\">kürzer (kyrtser) — kortere</div><div class=\"kurss-example\">Kunst (kunst) — kunst</div><div class=\"kurss-example\">Künste (kynste) — kunster</div><div class=\"kurss-example\">Mutter (muter) — mor</div><div class=\"kurss-example\">Mütter (myter) — mødre</div></div>\n              <p class=\"artikuli-explain\">ü er omlyden af u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftonger: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — træ</div><div class=\"kurss-example\">Bäume (bojme) — træer</div><div class=\"kurss-example\">Haus (haus) — hus</div><div class=\"kurss-example\">Häuser (hojzer) — huse</div><div class=\"kurss-example\">Strauch (sjtrauch) — busk</div><div class=\"kurss-example\">Sträucher (sjtrojcher) — buske</div><div class=\"kurss-example\">Maus (maus) — mus</div><div class=\"kurss-example\">Mäuse (mojze) — mus (flertal)</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftonger: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hojte) — i dag</div><div class=\"kurss-example\">Leute (lojte) — folk / mennesker</div><div class=\"kurss-example\">neu (noj) — ny</div><div class=\"kurss-example\">neun (nojn) — ni</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftonger: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (majn) — min</div><div class=\"kurss-example\">dein (dajn) — din</div><div class=\"kurss-example\">sein (zajn) — hans / sin / at være</div><div class=\"kurss-example\">frei (fraj) — fri</div><div class=\"kurss-example\">arbeiten (arbajten) — arbejde</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Udtalenoter til lektion 2</h4>\n              <ul class=\"kurss-summary-list\"><li>i ordene ich, nicht, rechnen, zeichnen udtales »ch« blødt (en hvislende lyd mellem dansk »sj« og »j«)</li><li>i ordene arbeiten og zeichnen udtales »ei« som »aj«</li><li>»sp« i begyndelsen af et ord udtales som »sjp«</li><li>i udsagnsordet tun udtales bogstavet »u« langt</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Opsummering</h4>\n              <ul class=\"kurss-summary-list\"><li>én konsonant efter vokalen → ofte lang vokal</li><li>to eller flere konsonanter → ofte kort vokal</li><li>h kan forlænge vokalen</li><li>ie betyder ofte langt i</li><li>dobbeltvokaler er normalt lange</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Konsonanter og bogstavkombinationer</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>På tysk udtales nogle konsonanter og bogstavkombinationer anderledes, end de skrives. I denne lektion finder du de vigtigste eksempler for begyndere.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Konsonanter</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (das rāt) — hjul</div><div class=\"kurss-example\">die Räder (dī rēder) — hjul (flertal)</div><div class=\"kurss-example\">Bad (bāt) — bad / badeværelse</div><div class=\"kurss-example\">Bäder (bēder) — bade / badeværelser</div></div>\n              <p class=\"artikuli-explain\">Sidst i et ord udtales konsonanterne ofte ikke, som de skrives (fx lyder d som t).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">»ch« kan udtales blødt eller hårdt. I nogle ord lyder det som et hvislende »h« (mellem dansk »sj« og »j«), i andre mere som en hæs lyd bagerst i halsen, tættere på »k«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rechnen) — regne</div><div class=\"kurss-example\">zeichnen (tsajchnen) — tegne</div><div class=\"kurss-example\">nicht (nicht) — ikke</div><div class=\"kurss-example\">schlecht (sjlecht) — dårlig</div><div class=\"kurss-example\">mich (mich) — mig</div><div class=\"kurss-example\">dich (dich) — dig</div><div class=\"kurss-example\">Strauch (sjtrauch) — busk</div><div class=\"kurss-example\">noch (noch) — endnu / stadig</div><div class=\"kurss-example\">Nacht (nacht) — nat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">»sch« udtales på tysk som dansk »sj« (som i »sjov«).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (sjūle) — skole</div><div class=\"kurss-example\">Schüler (sjȳler) — elev</div><div class=\"kurss-example\">Schiff (sjif) — skib</div><div class=\"kurss-example\">Schraube (sjraube) — skrue</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp og st i begyndelsen af et ord</h4>\n              <p class=\"artikuli-explain\">I begyndelsen af et ord eller en stavelse udtales »sp« ofte som »sjp« og »st« som »sjt«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (sjpīlen) — lege / spille</div><div class=\"kurss-example\">Sprung (sjprung) — spring</div><div class=\"kurss-example\">stehen (sjtēen) — stå</div><div class=\"kurss-example\">Stall (sjtal) — stald</div><div class=\"kurss-example\">Stand (sjtant) — stand / stade</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">»qu« udtales på tysk normalt som »kv«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvāl) — kval / pine</div><div class=\"kurss-example\">Quartier (kvartīr) — logi / kvarter</div><div class=\"kurss-example\">quer (kvēr) — på tværs</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s og z</h4>\n              <p class=\"artikuli-explain\">I begyndelsen af et ord lyder »s« ofte som et stemt s (som engelsk »z« i »zoo«) – i udtaleangivelserne skrevet »z«. Bogstavet »z« udtales på tysk som »ts«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zāgen) — sige</div><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">Rose (rōze) — rose</div><div class=\"kurss-example\">Zahl (tsāl) — tal</div><div class=\"kurss-example\">Zeit (tsajt) — tid</div><div class=\"kurss-example\">Zink (tsink) — zink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">På tysk udtales »v« ofte som »f«. I fremmedord lyder det ofte som dansk »v«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">von (fon) — fra / af</div><div class=\"kurss-example\">viel (fīl) — meget</div><div class=\"kurss-example\">vier (fīr) — fire</div><div class=\"kurss-example\">Villa (vila) — villa</div><div class=\"kurss-example\">Klavier (klavīr) — klaver</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x og y</h4>\n              <p class=\"artikuli-explain\">»x« udtales som »ks«. »y« udtales i nogle ord som »ü« (dansk »y«).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (fēliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — økse</div><div class=\"kurss-example\">Mystik (mystik) — mystik</div><div class=\"kurss-example\">Mythe (mȳte) — myte</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">»ß« udtales på tysk som et skarpt »s«.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fūs) — fod</div><div class=\"kurss-example\">Füße (fȳse) — fødder</div><div class=\"kurss-example\">Grüße (grȳse) — hilsener</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Opsummering</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st i begyndelsen → sjp / sjt</li><li>qu → kv</li><li>z → ts</li><li>v ofte → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Grundlæggende om verber</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Verber fra 1. lektion og deres former (bøjning)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Verber</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — at komme</div><div class=\"kurss-example\">gehen — at gå</div><div class=\"kurss-example\">stehen — at stå</div><div class=\"kurss-example\">singen — at synge</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — jeg kommer</div><div class=\"kurss-example\">du kommst — du kommer</div><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hun kommer</div><div class=\"kurss-example\">wir kommen — vi kommer</div><div class=\"kurss-example\">ihr kommt — I kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — jeg går</div><div class=\"kurss-example\">du gehst — du går</div><div class=\"kurss-example\">er geht — han går</div><div class=\"kurss-example\">sie geht — hun går</div><div class=\"kurss-example\">wir gehen — vi går</div><div class=\"kurss-example\">ihr geht — I går</div><div class=\"kurss-example\">sie gehen — de går</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — jeg står</div><div class=\"kurss-example\">du stehst — du står</div><div class=\"kurss-example\">er steht — han står</div><div class=\"kurss-example\">sie steht — hun står</div><div class=\"kurss-example\">wir stehen — vi står</div><div class=\"kurss-example\">ihr steht — I står</div><div class=\"kurss-example\">sie stehen — de står</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — jeg synger</div><div class=\"kurss-example\">du singst — du synger</div><div class=\"kurss-example\">er singt — han synger</div><div class=\"kurss-example\">sie singt — hun synger</div><div class=\"kurss-example\">wir singen — vi synger</div><div class=\"kurss-example\">ihr singt — I synger</div><div class=\"kurss-example\">sie singen — de synger</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Verber fra 2. lektion</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — at spille</div><div class=\"kurss-example\">arbeiten — at arbejde</div><div class=\"kurss-example\">fragen — at spørge</div><div class=\"kurss-example\">antworten — at svare</div><div class=\"kurss-example\">rechnen — at regne</div><div class=\"kurss-example\">zeichnen — at tegne</div><div class=\"kurss-example\">tun — at gøre</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — jeg spiller</div><div class=\"kurss-example\">du spielst — du spiller</div><div class=\"kurss-example\">er spielt — han spiller</div><div class=\"kurss-example\">sie spielt — hun spiller</div><div class=\"kurss-example\">wir spielen — vi spiller</div><div class=\"kurss-example\">ihr spielt — I spiller</div><div class=\"kurss-example\">sie spielen — de spiller</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — jeg arbejder</div><div class=\"kurss-example\">du arbeitest — du arbejder</div><div class=\"kurss-example\">er arbeitet — han arbejder</div><div class=\"kurss-example\">sie arbeitet — hun arbejder</div><div class=\"kurss-example\">wir arbeiten — vi arbejder</div><div class=\"kurss-example\">ihr arbeitet — I arbejder</div><div class=\"kurss-example\">sie arbeiten — de arbejder</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — jeg spørger</div><div class=\"kurss-example\">du fragst — du spørger</div><div class=\"kurss-example\">er fragt — han spørger</div><div class=\"kurss-example\">sie fragt — hun spørger</div><div class=\"kurss-example\">wir fragen — vi spørger</div><div class=\"kurss-example\">ihr fragt — I spørger</div><div class=\"kurss-example\">sie fragen — de spørger</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — jeg svarer</div><div class=\"kurss-example\">du antwortest — du svarer</div><div class=\"kurss-example\">er antwortet — han svarer</div><div class=\"kurss-example\">sie antwortet — hun svarer</div><div class=\"kurss-example\">wir antworten — vi svarer</div><div class=\"kurss-example\">ihr antwortet — I svarer</div><div class=\"kurss-example\">sie antworten — de svarer</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — jeg regner</div><div class=\"kurss-example\">du rechnest — du regner</div><div class=\"kurss-example\">er rechnet — han regner</div><div class=\"kurss-example\">sie rechnet — hun regner</div><div class=\"kurss-example\">wir rechnen — vi regner</div><div class=\"kurss-example\">ihr rechnet — I regner</div><div class=\"kurss-example\">sie rechnen — de regner</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — jeg tegner</div><div class=\"kurss-example\">du zeichnest — du tegner</div><div class=\"kurss-example\">er zeichnet — han tegner</div><div class=\"kurss-example\">sie zeichnet — hun tegner</div><div class=\"kurss-example\">wir zeichnen — vi tegner</div><div class=\"kurss-example\">ihr zeichnet — I tegner</div><div class=\"kurss-example\">sie zeichnen — de tegner</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — jeg gør</div><div class=\"kurss-example\">du tust — du gør</div><div class=\"kurss-example\">er tut — han gør</div><div class=\"kurss-example\">sie tut — hun gør</div><div class=\"kurss-example\">wir tun — vi gør</div><div class=\"kurss-example\">ihr tut — I gør</div><div class=\"kurss-example\">sie tun — de gør</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Sætningsopbygning</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>I et spørgsmål står verbet på tysk normalt på førstepladsen.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Eksempler</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Du kommer.</div><div class=\"kurss-example\">Kommst du? — Kommer du?</div><div class=\"kurss-example\">Er singt. — Han synger.</div><div class=\"kurss-example\">Singt er? — Synger han?</div><div class=\"kurss-example\">Stehst du? — Står du?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, jeg står.</div><div class=\"kurss-example\">Geht ihr? — Går I?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, vi går.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Spørgsmål med “was”</h4>\n              <p class=\"artikuli-explain\">Hvis et spørgsmål begynder med et spørgeord, står verbet på tysk normalt lige efter spørgeordet.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Hvad laver du?</div><div class=\"kurss-example\">Was tut er? — Hvad laver han?</div><div class=\"kurss-example\">Was tut sie? — Hvad laver hun?</div><div class=\"kurss-example\">Was tun sie? — Hvad laver de?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Nægtelse med “nicht”</h4>\n              <p class=\"artikuli-explain\">Hvis nægtelsen “nicht” hører til verbet, står den på tysk normalt efter verbet.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Jeg spiller ikke.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul spørger ikke.</div><div class=\"kurss-example\">Er kommt nicht. — Han kommer ikke.</div><div class=\"kurss-example\">Sie singen nicht. — De synger ikke.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Sætninger fra lektion 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Spiller du?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nej, jeg spiller ikke, jeg arbejder.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul spørger ikke, han arbejder.</div><div class=\"kurss-example\">Arbeitest du? — Arbejder du?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nej, jeg arbejder ikke, jeg synger.</div><div class=\"kurss-example\">Was tut Paul? — Hvad laver Paul?</div><div class=\"kurss-example\">Er spielt. — Han spiller.</div><div class=\"kurss-example\">Was tut Marie? — Hvad laver Marie?</div><div class=\"kurss-example\">Sie singt. — Hun synger.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul spiller, men Marie synger.</div><div class=\"kurss-example\">Singt ihr? — Synger I?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nej, vi synger ikke, vi arbejder.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Hvad laver Paul og Marie?</div><div class=\"kurss-example\">Sie fragen. — De spørger.</div><div class=\"kurss-example\">Sie antworten nicht. — De svarer ikke.</div><div class=\"kurss-example\">Wer arbeitet? — Hvem arbejder?</div><div class=\"kurss-example\">Wir arbeiten. — Vi arbejder.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Vi regner og tegner.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — De kommer, spørger, svarer, arbejder, spiller, synger og går.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lektion 2</h3>\n            <p class=\"kurss-lesson-intro\">Anden lektion: dialoger, ord, udtale, grammatik og oversættelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — lege; spille</div>\n                  <div class=\"kurss-example\">nein — nej</div>\n                  <div class=\"kurss-example\">nicht — ikke</div>\n                  <div class=\"kurss-example\">arbeiten — arbejde</div>\n                  <div class=\"kurss-example\">fragen — spørge</div>\n                  <div class=\"kurss-example\">was tut er? — hvad laver han?</div>\n                  <div class=\"kurss-example\">was tun sie? — hvad laver de?</div>\n                  <div class=\"kurss-example\">aber — men</div>\n                  <div class=\"kurss-example\">antworten — svare</div>\n                  <div class=\"kurss-example\">rechnen — regne</div>\n                  <div class=\"kurss-example\">zeichnen — tegne</div>\n                  <div class=\"kurss-example\">Marie — Marie</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I ordene ich, nicht, rechnen, zeichnen udtales ch blødt: lyden findes ikke på dansk og lyder som et hvæsende, ustemt j – tungen hæves mod den hårde gane, og luften presses ud.</div><div class=\"kurss-example\">I ordene arbeiten, zeichnen udtales diftongen ei omtrent som dansk aj i »maj«.</div><div class=\"kurss-example\">Konsonantforbindelsen sp udtales som sjp: spielen (sjpiilen).</div><div class=\"kurss-example\">I verbet tun udtales u langt i alle personer.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Endelser med e</h4>\n                  <div class=\"lesson1-grammar-note\">Ender verbets stamme på t, d, chn, indskydes der ved bøjningen et e foran endelserne -st og -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Spørgeord</h4>\n                  <div class=\"lesson1-grammar-note\">I spørgesætninger, der begynder med et spørgeord, fx: hvad? hvem? hvilken? hvorfor? osv., står verbet lige efter spørgeordet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Hvad laver du?</div><div class=\"kurss-example\">Was tut er? — Hvad laver han?</div><div class=\"kurss-example\">Was tut sie? — Hvad laver hun?</div><div class=\"kurss-example\">Was tun sie? — Hvad laver de?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Nægtelse med nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Når nægtelsen nicht hører til verbet, står nægtelsesordet efter verbet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Han kommer ikke.</div><div class=\"kurss-example\">Sie singen nicht. — De synger ikke.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 2 – oversættelseskort\">\n                    <span class=\"lesson1-training-progress\">Lektion 2 · Oversæt: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Hvem spørger?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lektion 6</h3>\n    <p class=\"kurss-lesson-intro\">Talord, flertal, omlyd og navneordenes flertalsformer.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — befinder sig, er, ligger</div><div class=\"kurss-example\">der Bleistift (blajsjtift) — blyant</div><div class=\"kurss-example\">einige (ajnige) — nogle</div><div class=\"kurss-example\">hinlegen — lægge fra sig</div><div class=\"kurss-example\">legt hin — lægger fra sig</div><div class=\"kurss-example\">wieder (viider) — igen</div><div class=\"kurss-example\">aufmachen — åbne, lukke op</div><div class=\"kurss-example\">er macht auf — han åbner</div><div class=\"kurss-example\">anspitzen (ansjpitsen) — spidse</div><div class=\"kurss-example\">er spitzt an — han spidser</div><div class=\"kurss-example\">sich setzen — sætte sig</div><div class=\"kurss-example\">setzt sich — sætter sig</div><div class=\"kurss-example\">der Schlüssel (sjlyssel) — nøgle</div><div class=\"kurss-example\">das Fenster (fenster) — vindue</div><div class=\"kurss-example\">die Tafel (dii taafel) — tavle</div><div class=\"kurss-example\">der Garten — have</div><div class=\"kurss-example\">der Löffel — ske</div><div class=\"kurss-example\">zählen (tsæælen) — tælle</div><div class=\"kurss-example\">die Nadel — nål</div><div class=\"kurss-example\">was ist das — hvad er det?</div><div class=\"kurss-example\">der Hammer — hammer</div><div class=\"kurss-example\">die Hämmer — hamre</div><div class=\"kurss-example\">der Deckel (deer dekkel) — låg</div><div class=\"kurss-example\">der Teller — tallerken</div><div class=\"kurss-example\">der Wagen — vogn</div><div class=\"kurss-example\">der Schlitten — slæde, kane</div><div class=\"kurss-example\">das Ding — ting</div><div class=\"kurss-example\">die Dinge — ting</div><div class=\"kurss-example\">wie sind die Dinge? — hvordan er tingene?</div><div class=\"kurss-example\">voll (fol) — fuld</div><div class=\"kurss-example\">leer (leer) — tom</div><div class=\"kurss-example\">schwer (sjveer) — tung, svær</div><div class=\"kurss-example\">leicht — let</div><div class=\"kurss-example\">der Eimer — spand</div><div class=\"kurss-example\">wieviel (viifiil) — hvor mange, hvor meget</div><div class=\"kurss-example\">wieviel Nadeln — hvor mange nåle</div><div class=\"kurss-example\">hier (hiir) — her</div><div class=\"kurss-example\">dort — der</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä er omlyd af vokalen a og udtales som et kort eller langt æ.</div><div class=\"kurss-example\">Eksempler: das Mädchen (mæætchen), die Bänke (dii bænke), der Vater (deer faater), die Väter (dii fææter).</div><div class=\"kurss-example\">ü er omlyd af vokalen u og udtales som dansk y: læberne rundes kraftigt, og med runde læber forsøger man at sige i.</div><div class=\"kurss-example\">Eksempler: fünf, der Schlüssel (sjlyssel).</div><div class=\"kurss-example\">ö udtales som dansk ø – med runde læber, mens man forsøger at sige e: der Löffel.</div><div class=\"kurss-example\">En dobbelt vokal betegner en lang vokal: leer (leer).</div><div class=\"kurss-example\">Diftongen eu udtales som oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatik og forklaringer</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Den betonede forstavelse i et sammensat verbum skilles i nutid fra verbet og står sidst i sætningen.</div><div class=\"kurss-example\">Eksempler: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Talordet en har former i alle tre køn, når det bruges sammen med et navneord: i hankøn ein, i hunkøn eine, i intetkøn ein.</div><div class=\"kurss-example\">Eksempler: ein Schüler — en elev; eine Schülerin — en skolepige; ein Kind — et barn.</div><div class=\"kurss-example\">Talord: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (nojn), zehn (tseen).</div><div class=\"kurss-example\">Verbet være har på tysk en form i ental og en anden i flertal: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Det påpegende stedord har på tysk i denne forbindelse kun én form, ligesom dansk det i »det er …«: das.</div><div class=\"kurss-example\">Eksempler: det er en hammer — das ist ein Hammer; det er en nål — das ist eine Nadel; det er hamre — das sind Hämmer; det er nåle — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vogn og der Schlitten — slæde bruges på tysk ligesom på dansk både i ental og i flertal.</div><div class=\"kurss-example\">Hankøns- og intetkønsord med endelsen -er, -el, -en får ofte ingen endelse i flertal.</div><div class=\"kurss-example\">Eksempler: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Hunkønsord med endelsen -el, -er får -n i flertal.</div><div class=\"kurss-example\">Eksempler: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Undtagelser: die Mutter (mor) — die Mütter (mødre); die Tochter (datter) — die Töchter (døtre).</div><div class=\"kurss-example\">Det ubestemte kendeord har intet flertal: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">I en fremsættende sætning står udsagnsleddet på andenpladsen: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 6 – oversættelseskort\"><span class=\"lesson1-training-progress\">Lektion 6 · Oversæt: 1 / 21</span><span class=\"lesson1-training-text\">Paul tager en blyant og tegner.</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lektion 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akkusativ, sitzen, fragen og endelsen -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — sidde</div>\n        <div class=\"kurss-example\">fragen (fraagen) — spørge</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — lærer</div>\n        <div class=\"kurss-example\">gut (guut) — godt</div>\n        <div class=\"kurss-example\">wen (veen) — hvem</div>\n        <div class=\"kurss-example\">loben — rose</div>\n        <div class=\"kurss-example\">der Schüler (sjyyler) — elev</div>\n        <div class=\"kurss-example\">klein — lille</div>\n        <div class=\"kurss-example\">groß (groos) — stor</div>\n        <div class=\"kurss-example\">die Lehrerin — lærerinde</div>\n        <div class=\"kurss-example\">die Schülerin — skolepige, kvindelig elev</div>\n        <div class=\"kurss-example\">schlecht (sjlecht) — dårligt</div>\n        <div class=\"kurss-example\">tadeln — dadle, skælde ud</div>\n        <div class=\"kurss-example\">oder (ooder) — eller</div>\n        <div class=\"kurss-example\">das Kind (kint) — barn</div>\n        <div class=\"kurss-example\">artig (aartich) — artig</div>\n        <div class=\"kurss-example\">die Mutter — mor</div>\n        <div class=\"kurss-example\">lieben (liiben) — elske</div>\n        <div class=\"kurss-example\">der Vater (faater) — far</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz er et fordoblet z og udtales som tysk z, altså ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">v udtales i tyske ord som f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß kaldes eszett og udtales som dansk s: groß (groos), weiß (vajs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ og akkusativ</h4><div class=\"lesson1-grammar-note\">På dansk bøjes navneord ikke i kasus: grundleddet, der svarer til nominativ, svarer på spørgsmålet hvem? eller hvad?, og genstandsleddet, der svarer til akkusativ, ligeledes på hvem? eller hvad?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tysk er spørgeordet i nominativ wer? for personer og was? for ting.</div><div class=\"kurss-example\">I akkusativ er spørgeordet wen? for personer og was? for ting.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Kendeordenes ændring i akkusativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akkusativ</h4><div class=\"lesson1-grammar-note\">Verbet fragen styrer på tysk akkusativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Endelsen -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mange hunkønsord dannes med endelsen -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verbets plads</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I en fremsættende sætning står verbet på andenpladsen.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 5 – oversættelseskort\"><span class=\"lesson1-training-progress\">Lektion 5 · Oversæt: 1 / 16</span><span class=\"lesson1-training-text\">Hvem er det, faren elsker?</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lektion 4</h3>\n            <p class=\"kurss-lesson-intro\">Akkusativ, nehmen, hinlegen, hinausgehen og tillægsord.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — tage</div><div class=\"kurss-example\">er nimmt (nimt) — han tager</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — penneskaft</div><div class=\"kurss-example\">einen Federhalter — penneskaft</div><div class=\"kurss-example\">zeigen — vise</div><div class=\"kurss-example\">schwarz (sjvarts) — sort</div><div class=\"kurss-example\">weiß (vajs) — hvid</div><div class=\"kurss-example\">die Feder (dii feeder) — pen</div><div class=\"kurss-example\">eine Feder — pen</div><div class=\"kurss-example\">spitz (sjpits) — spids</div><div class=\"kurss-example\">hinlegen — lægge fra sig</div><div class=\"kurss-example\">legt hin — lægger fra sig</div><div class=\"kurss-example\">das Mädchen (mæætchen) — pige</div><div class=\"kurss-example\">das Messer — kniv</div><div class=\"kurss-example\">ein Messer — kniv</div><div class=\"kurss-example\">scharf — skarp</div><div class=\"kurss-example\">stumpf (sjtumpf) — sløv, stump</div><div class=\"kurss-example\">dann — så, derefter</div><div class=\"kurss-example\">hinaus — ud</div><div class=\"kurss-example\">hinausgehen — gå ud</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Endelserne -en, -er, -el er tryksvage, derfor høres e i disse endelser kun svagt: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h kan på tysk være både en lyd og et længdetegn for den foregående vokal.</div><div class=\"kurss-example\">Når h er længdetegn, udtales det ikke som en lyd: nehmen (neemen).</div><div class=\"kurss-example\">Følger der kun én konsonant efter en vokal, udtales vokalen lang: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akkusativ</h4><div class=\"lesson1-grammar-note\">I hunkøn og intetkøn er akkusativ det samme som nominativ. Kun hankøn ændrer sig.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Stedord</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — hankøn</div><div class=\"kurss-example\">sie — hunkøn</div><div class=\"kurss-example\">es — intetkøn</div><div class=\"kurss-example\">i flertal — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Adskillelige verber</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Tillægsord</h4><div class=\"lesson1-grammar-note\">Når tillægsordet i sætningen er omsagnsled, bøjes det hverken i køn eller tal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Nægtelse med nicht</h4><div class=\"lesson1-grammar-note\">Når nicht nægter et tillægsord, står det foran det nægtede ord.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Navneord med endelsen -chen og -lein er intetkøn: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 4 – oversættelseskort\"><span class=\"lesson1-training-progress\">Lektion 4 · Oversæt: 1 / 16</span><span class=\"lesson1-training-text\">Pigen tager et penneskaft.</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lektion 3</h3>\n            <p class=\"kurss-lesson-intro\">Tredje lektion: dialoger, ord, udtale, grammatik og oversættelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — hvem</div><div class=\"kurss-example\">was — hvad</div><div class=\"kurss-example\">hier — her</div><div class=\"kurss-example\">dort — der, derhenne</div><div class=\"kurss-example\">der Tisch — bord</div><div class=\"kurss-example\">ein Tisch — bord</div><div class=\"kurss-example\">die Bank — bænk</div><div class=\"kurss-example\">eine Bank — bænk</div><div class=\"kurss-example\">liegen — ligge</div><div class=\"kurss-example\">liegt hier ein Buch? — er der / ligger der en bog her?</div><div class=\"kurss-example\">das Buch — bog</div><div class=\"kurss-example\">ein Buch — bog</div><div class=\"kurss-example\">hängen — hænge</div><div class=\"kurss-example\">das Bild — billede</div><div class=\"kurss-example\">ein Bild — billede</div><div class=\"kurss-example\">die Tafel — tavle</div><div class=\"kurss-example\">eine Tafel — tavle</div><div class=\"kurss-example\">wie — hvordan</div><div class=\"kurss-example\">ist — er</div><div class=\"kurss-example\">dick — tyk</div><div class=\"kurss-example\">das Heft — hæfte</div><div class=\"kurss-example\">ein Heft — hæfte</div><div class=\"kurss-example\">dünn — tynd</div><div class=\"kurss-example\">niedrig — lav</div><div class=\"kurss-example\">hoch — høj</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Det lange i skrives på tysk ie: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck er et dobbelt k: dick (dikk).</div><div class=\"kurss-example\">I tillægsord og biord lyder endelsen -ig som et blødt -ich: niedrig (niidrich).</div><div class=\"kurss-example\">Følger der et e efter -ig: -ige, udtales g som et tydeligt g: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Grundled</h4><div class=\"lesson1-grammar-note\">Grundleddet svarer på tysk på spørgsmålet wer? / was? og står i nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Med wer? spørger man om personer.</div><div class=\"kurss-example\">Med was? spørger man om ting.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Kendeord</h4><div class=\"lesson1-grammar-note\">Navneord har på tysk 3 køn: hankøn, hunkøn og intetkøn. Foran navneord står der som regel et lille ord, som kaldes kendeord. Dette ord oversættes ikke.</div><h5 class=\"lesson2-subtitle\">Bestemt kendeord</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankøn — der</div><div class=\"kurss-example\">hunkøn — die</div><div class=\"kurss-example\">intetkøn — das</div><div class=\"kurss-example\">I flertal er det bestemte kendeord die for alle tre køn.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Ubestemt kendeord</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankøn — ein</div><div class=\"kurss-example\">hunkøn — eine</div><div class=\"kurss-example\">intetkøn — ein</div><div class=\"kurss-example\">Det ubestemte kendeord har intet flertal.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Egennavne</h4><div class=\"lesson1-grammar-note\">Foran egennavne bruges der intet kendeord.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbets plads</h4><div class=\"lesson1-grammar-note\">I en fremsættende sætning står verbet på andenpladsen.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Om ting, der står lodret, siger man på tysk, at de står:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Om ting, der befinder sig i vandret stilling, siger man, at de ligger:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Ting kan også hænge:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 3 – oversættelseskort\"><span class=\"lesson1-training-progress\">Lektion 3 · Oversæt: 1 / 22</span><span class=\"lesson1-training-text\">Regner du?</span></button><p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lektion 7</h3>\n            <p class=\"kurss-lesson-intro\">Syvende lektion: bydeform, høflig tiltale og flertal.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / sætninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — synge</div><div class=\"kurss-example\">singe — syng</div><div class=\"kurss-example\">singt — syng</div><div class=\"kurss-example\">singen Sie — syng</div><div class=\"kurss-example\">das Lied (das liit) — sang</div><div class=\"kurss-example\">Sie — De</div><div class=\"kurss-example\">zählen — tælle</div><div class=\"kurss-example\">das Fräulein (frojlajn) — frøken</div><div class=\"kurss-example\">der Müller — møller</div><div class=\"kurss-example\">öffnen — åbne</div><div class=\"kurss-example\">das Fenster (fenster) — vindue</div><div class=\"kurss-example\">alle — alle</div><div class=\"kurss-example\">der Spiegel (sjpiigel) — spejl</div><div class=\"kurss-example\">der Lappen — klud</div><div class=\"kurss-example\">der Spaten — spade</div><div class=\"kurss-example\">der Besen — kost</div><div class=\"kurss-example\">die Schaufel — skovl</div><div class=\"kurss-example\">die Schüssel — skål</div><div class=\"kurss-example\">das Zimmer — værelse</div><div class=\"kurss-example\">das Ufer (uufer) — bred</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp i begyndelsen af et ord eller en stavelse udtales som sjp: der Spiegel (deer sjpiigel).</div><div class=\"kurss-example\">sch udtales som dansk sj i »sjov«: die Schaufel (dii sjaufel), die Schüssel (dii sjyssel).</div><div class=\"kurss-example\">Diftongen äu udtales som oj i »ahoj«: das Fräulein (das frojlajn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Bydeform</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Bydeformen i 2. person ental svarer til verbets 2. person ental uden personendelsen -st, men med endelsen -e.</div><div class=\"kurss-example\">Eksempler: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Meget ofte udelades endelsen -e, når bydeformen uden den er enstavelses: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Bydeform i flertal</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Bydeformen i 2. person flertal er lig med 2. person flertal i nutid, men bruges uden stedord.</div><div class=\"kurss-example\">Eksempler: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Høflig tiltale med Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Den høflige tiltaleform »De« er lig med 3. person flertal. Stedordet Sie skrives med stort begyndelsesbogstav og står efter verbet.</div><div class=\"kurss-example\">Eksempler: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">For at lette udtalen indskyder verbet öffnen et e mellem stamme og endelse i 2. og 3. person ental og 2. person flertal: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Øvelse</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 7 – øvelseskort\"><span class=\"lesson1-training-progress\">Lektion 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — spørge</span></button><p class=\"lesson1-training-hint\">Tryk på kortet for at se bydeformerne.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lektion 1</h3>\n            <p class=\"kurss-lesson-intro\">Første lektion: verber i nutid, gloser, udtale, grammatik og oversættelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verber i nutid</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verber og deres bøjning i nutid.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — komme</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>jeg kommer</span><span>du</span><strong>kommst</strong><span>du kommer</span><span>er / sie</span><strong>kommt</strong><span>han / hun kommer</span><span>wir</span><strong>kommen</strong><span>vi kommer</span><span>ihr</span><strong>kommt</strong><span>I kommer</span><span>sie / Sie</span><strong>kommen</strong><span>de / De kommer</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>jeg går</span><span>du</span><strong>gehst</strong><span>du går</span><span>er / sie</span><strong>geht</strong><span>han / hun går</span><span>wir</span><strong>gehen</strong><span>vi går</span><span>ihr</span><strong>geht</strong><span>I går</span><span>sie / Sie</span><strong>gehen</strong><span>de / De går</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>jeg står</span><span>du</span><strong>stehst</strong><span>du står</span><span>er / sie</span><strong>steht</strong><span>han / hun står</span><span>wir</span><strong>stehen</strong><span>vi står</span><span>ihr</span><strong>steht</strong><span>I står</span><span>sie / Sie</span><strong>stehen</strong><span>de / De står</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — synge</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>jeg synger</span><span>du</span><strong>singst</strong><span>du synger</span><span>er / sie</span><strong>singt</strong><span>han / hun synger</span><span>wir</span><strong>singen</strong><span>vi synger</span><span>ihr</span><strong>singt</strong><span>I synger</span><span>sie / Sie</span><strong>singen</strong><span>de / De synger</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Eksempler</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Gloser</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Ordenes omtrentlige udtale står i parentes med danske bogstaver.<br>Det gælder også i de følgende lektioner.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — vi</div><div class=\"kurss-example\">I ordet »wir« udtales i langt.</div><div class=\"kurss-example\">kommen (kommen) — komme</div><div class=\"kurss-example\">gehen (gee-en) — gå</div><div class=\"kurss-example\">stehen (sjtee-en) — stå</div><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">du (duu) kommst — du kommer</div><div class=\"kurss-example\">er (eer) kommt — han kommer</div><div class=\"kurss-example\">sie (zii) kommt — hun kommer</div><div class=\"kurss-example\">wer (veer) — hvem?</div><div class=\"kurss-example\">ja (jaa) — ja</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Udtale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ordenes korrekte udtale, skrevet med danske bogstaver, er angivet i lektionerne.</div><div class=\"kurss-example\">Wir (viir) — vi. I ordet wir udtales i altid langt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Verbets grundform. Infinitiv ender som regel på -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Nutidsendelser</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Fjern <span class=\"lesson1-ending-accent\">-en</span> fra verbets grundform og tilføj endelsen.</strong></p><p>Eksempel: kommen → komm + endelse</p><div class=\"lesson1-ending-process\" aria-label=\"Sådan dannes nutidsendelserne\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grundform</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>fjern <span class=\"lesson1-ending-accent\">-en</span></strong><span>stammen bliver tilbage</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stamme</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>tilføj endelsen</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Eksempler</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Spørgesætninger</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>I en tysk spørgesætning flytter verbet som regel op på førstepladsen.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På dansk:<br>Du kommer.<br>Kommer du?</div><div class=\"kurss-example\">På tysk:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — du kommer<br>kommst du? — kommer du?</div><div class=\"kurss-example\">er singt — han synger<br>singt er? — synger han?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Forskel i person</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hun kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversæt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 1 – øvekort\">\n                    <span class=\"lesson1-training-progress\">Lektion 1 · Oversæt: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kommer du?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klik på kortet for at se den tyske oversættelse. Efter svaret viser næste klik det næste kort.</p>\n                </div>\n              </div>\n            </details>"
};

